package com.argument.draft;

import com.argument.common.exception.*;
import com.argument.integration.*;
import com.argument.version.*;
import com.argument.version.port.*;
import com.argument.version.port.VersionIdentity.Actor;
import com.argument.relation.dto.*;
import com.argument.relation.rules.RelationRules;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import static com.argument.adjudication.AdjudicationService.require;

/** C's pure rules/graph engine with the shared draft transaction and frozen public projections. */
@Service
public class StructureService {
    private final DraftService drafts;private final AnnotationDependencies data;private final StructureEngine engine;private final ObjectMapper mapper;private final StructureCommandValidator validator;private final SubmissionChecks checks;private final SharedSnapshotReader reader;private final VersionRepository versions;
    public StructureService(DraftService drafts,AnnotationDependencies data,StructureEngine engine,ObjectMapper mapper,StructureCommandValidator validator,SubmissionChecks checks,SharedSnapshotReader reader,VersionRepository versions){this.drafts=drafts;this.data=data;this.engine=engine;this.mapper=mapper;this.validator=validator;this.checks=checks;this.reader=reader;this.versions=versions;}
    private List<ObjectNode> relations(String id){return drafts.owned("relation",id).stream().filter(r->"ACTIVE".equals(r.path("status").asText())).sorted(Comparator.comparing(r->r.path("id").asText())).toList();}
    private List<ObjectNode> parts(List<ObjectNode> rs){var ps=new ArrayList<ObjectNode>();for(var r:rs)ps.addAll(data.find("participant","relationId",r.path("id").asText()));return ps;}
    private ObjectNode relation(Actor actor,String id){var r=data.read("relation",VersionJson.uuid(id));require("DRAFT".equals(r.path("ownerType").asText()),ErrorCode.FORBIDDEN,"不能编辑冻结关系");drafts.own(actor,r.path("ownerId").asText());return r;}
    private void valid(StructureEngine.Result result){var errors=result.issues().stream().filter(i->"ERROR".equals(i.level())).toList();if(!errors.isEmpty()){var first=errors.get(0);throw new VersionFailure("RELATION_CYCLE".equals(first.code())?ErrorCode.RELATION_CYCLE:ErrorCode.INVALID_PARTICIPANT,first.message(),Map.of("issues",errors));}}
    private List<ObjectNode> newParts(Actor actor,String id,JsonNode body){var ps=new ArrayList<ObjectNode>();for(var input:body){var p=mapper.createObjectNode();VersionJson.stamp(p,actor.id(),VersionJson.now());p.put("relationId",id);for(String f:List.of("ordinal","role","targetKind","targetId"))p.set(f,input.get(f));ps.add(p);}return ps;}
    private void normalize(List<ObjectNode> ps,String code,List<ObjectNode> es){var ordered=engine.normalize(code,es,StructureEngine.inputs(ps));for(var p:ps)for(var input:ordered)if(input.targetId().equals(p.path("targetId").asText())&&input.targetKind().equals(p.path("targetKind").asText()))p.put("ordinal",input.ordinal());}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public ObjectNode list(Actor actor,String id,int page,int size){drafts.own(actor,id);require(page>=1&&size>=1&&size<=100,ErrorCode.VALIDATION_ERROR,"分页范围错误");var rs=relations(id);var result=mapper.createObjectNode();var items=result.putObject("data").putArray("items");rs.stream().skip((long)(page-1)*size).limit(size).forEach(r->items.addObject().put("id",r.path("id").asText()).put("relationCode",r.path("relationCode").asText()).put("directed",r.path("directed").asBoolean()));result.put("total",rs.size());return result;}
    @Transactional
    public ObjectNode create(Actor actor,String id,String key,ObjectNode body){validator.validate("R02",body);var d=drafts.lockDraft(actor,id);var cached=drafts.replay(actor,"R02:"+id,key,body);if(cached!=null)return cached;drafts.writable(d);var before=d.deepCopy();String code=body.path("relationCode").asText();var doc=data.read("taskDocument",d.path("taskDocumentId").asText());String guide=data.read("task",doc.path("taskId").asText()).path("guideVersionId").asText();var defs=data.find("relationDefinition","guideVersionId",guide).stream().filter(r->code.equals(r.path("code").asText())).toList();require(defs.size()==1&&defs.get(0).path("directed").asBoolean()==RelationRules.isDirected(code),ErrorCode.SOURCE_INCOMPLETE,"绑定指南关系定义不完整");
        var r=mapper.createObjectNode();VersionJson.stamp(r,actor.id(),VersionJson.now());r.put("ownerType","DRAFT").put("ownerId",id).put("relationCode",code).put("directed",RelationRules.isDirected(code)).put("status","ACTIVE");r.set("relationDefinitionId",defs.get(0).get("id"));r.putArray("sourceRelationIds");var rs=new ArrayList<>(relations(id));var ps=parts(rs);var added=newParts(actor,r.path("id").asText(),body.path("participants"));rs.add(r);ps.addAll(added);var es=drafts.orderedElements(id);valid(engine.inspect(id,es,rs,ps));normalize(added,code,es);drafts.append("relation",r);added.forEach(p->drafts.append("participant",p));var ids=d.putArray("relationIds");rs.forEach(row->ids.add(row.path("id").asText()));drafts.touchDraft(d,actor);drafts.invalidateGraph(d,actor);data.replace("draft",d);var response=mapper.createObjectNode().put("id",r.path("id").asText()).put("directed",r.path("directed").asBoolean());drafts.saveReceipt(actor,"R02:"+id,key,body,response,before,d);return response;}
    @Transactional
    public ObjectNode replace(Actor actor,String id,String key,int expected,ObjectNode body){validator.validate("R03",body);var r=relation(actor,id);var d=drafts.lockDraft(actor,r.path("ownerId").asText());r=data.lock("relation",id);var cached=drafts.replay(actor,"R03:"+id,key,body);if(cached!=null)return cached;drafts.writable(d);drafts.version(r,expected,"Relation");require("ACTIVE".equals(r.path("status").asText()),ErrorCode.LOCKED_RESOURCE,"关系已移除");var before=r.deepCopy();var rs=relations(d.path("id").asText());var ps=new ArrayList<>(parts(rs));ps.removeIf(p->id.equals(p.path("relationId").asText()));var added=newParts(actor,id,body.path("participants"));ps.addAll(added);var es=drafts.orderedElements(d.path("id").asText());valid(engine.inspect(d.path("id").asText(),es,rs,ps));normalize(added,r.path("relationCode").asText(),es);
        // Preserve old participant facts as tombstones; frozen version participants are independent copies.
        for(var old:data.find("participant","relationId",id)){var tomb=old.deepCopy();drafts.append("replacedParticipant",tomb);}removeParticipants(id);added.forEach(p->drafts.append("participant",p));drafts.touch(r,actor);data.replace("relation",r);drafts.touchDraft(d,actor);drafts.invalidateGraph(d,actor);data.replace("draft",d);var response=mapper.createObjectNode().put("relationId",id).put("participantCount",added.size());drafts.saveReceipt(actor,"R03:"+id,key,body,response,before,r);return response;}
    private void removeParticipants(String id){for(var old:data.find("participant","relationId",id))dataRemove("participant",old.path("id").asText());}
    @org.springframework.beans.factory.annotation.Autowired private org.springframework.jdbc.core.JdbcTemplate jdbc;
    private void dataRemove(String kind,String id){jdbc.update("DELETE FROM workflow_records WHERE object_kind=? AND object_id=?",kind,id);}
    @Transactional
    public ObjectNode remove(Actor actor,String id,String key,int expected,ObjectNode body){validator.validate("R04",body);var r=relation(actor,id);var d=drafts.lockDraft(actor,r.path("ownerId").asText());r=data.lock("relation",id);var cached=drafts.replay(actor,"R04:"+id,key,body);if(cached!=null)return cached;drafts.writable(d);drafts.version(r,expected,"Relation");require("ACTIVE".equals(r.path("status").asText()),ErrorCode.LOCKED_RESOURCE,"关系已移除");require(!body.path("reason").asText().isBlank(),ErrorCode.VALIDATION_ERROR,"请填写删除理由");for(var outer:relations(d.path("id").asText()))for(var p:data.find("participant","relationId",outer.path("id").asText()))require(!("RELATION".equals(p.path("targetKind").asText())&&id.equals(p.path("targetId").asText())),ErrorCode.RELATION_IN_USE,"请先处理外层关系引用");var before=r.deepCopy();r.put("status","REMOVED");drafts.touch(r,actor);data.replace("relation",r);var ids=d.putArray("relationIds");relations(d.path("id").asText()).forEach(row->ids.add(row.path("id").asText()));drafts.touchDraft(d,actor);drafts.invalidateGraph(d,actor);data.replace("draft",d);var response=mapper.createObjectNode().put("status","REMOVED");drafts.saveReceipt(actor,"R04:"+id,key,body,response,before,r);return response;}
    @Transactional
    public ObjectNode validate(Actor actor,String id,String key,int expected,ObjectNode body){validator.validate("GR02",body);var d=drafts.lockDraft(actor,id);var cached=drafts.replay(actor,"GR02:"+id,key,body);if(cached!=null)return cached;drafts.writable(d);drafts.version(d,expected,"AnnotationDraft");var before=d.deepCopy();var es=drafts.orderedElements(id);var rs=relations(id);var ps=parts(rs);var result=engine.inspect(id,es,rs,ps);var issues=new ArrayList<>(result.issues());var eids=es.stream().filter(e->e.path("isProposition").asBoolean()).map(e->e.path("id").asText()).collect(java.util.stream.Collectors.toSet());var rids=rs.stream().map(r->r.path("id").asText()).collect(java.util.stream.Collectors.toSet());require(set(body.path("elementIds")).equals(eids)&&set(body.path("relationIds")).equals(rids),ErrorCode.CONFLICT,"请刷新并校验草稿全部命题和关系，不能仅提交子集");
        boolean fresh=!d.hasNonNull("graphId");var g=fresh?mapper.createObjectNode():data.lock("graph",d.path("graphId").asText());if(fresh)VersionJson.stamp(g,actor.id(),VersionJson.now());else drafts.touch(g,actor);g.put("ownerType","DRAFT").put("ownerId",id).put("status","VALID");g.set("elementIds",mapper.valueToTree(es.stream().filter(e->e.path("isProposition").asBoolean()).map(e->e.path("id").asText()).toList()));g.set("relationIds",mapper.valueToTree(rs.stream().map(r->r.path("id").asText()).toList()));g.put("componentCount",result.graph().componentCount());var doc=data.read("taskDocument",d.path("taskDocumentId").asText());try{checks.check(d,data.read("task",doc.path("taskId").asText()),doc,data.read("checkpoint",d.path("segmentationCheckpointId").asText()),es,rs,ps,g);}catch(BusinessException e){issues.add(RelationIssue.error(e.getErrorCode().getCode(),e.getMessage()));}
        for(String isolated:result.graph().isolatedNodeIds())issues.add(RelationIssue.warning("ISOLATED_PROPOSITION","存在孤立命题，请人工核对是否遗漏关系").at(null,null));g.put("status",issues.stream().anyMatch(i->"ERROR".equals(i.level()))?"INVALID":"VALID");if(fresh)drafts.append("graph",g);else data.replace("graph",g);d.set("graphId",g.get("id"));drafts.touchDraft(d,actor);data.replace("draft",d);var response=mapper.createObjectNode().put("status",g.path("status").asText());response.set("issues",mapper.valueToTree(issues));drafts.saveReceipt(actor,"GR02:"+id,key,body,response,before,d);return response;}
    private Set<String> set(JsonNode rows){var result=new HashSet<String>();for(var id:rows)require(result.add(id.asText()),ErrorCode.VALIDATION_ERROR,"重复的对象 ID");return result;}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public ObjectNode preview(Actor actor,String id){var d=drafts.own(actor,id);var c=d.path("taskDocumentId").asText();var result=workspace(actor,c);require(result.path("draft").path("id").asText().equals(id),ErrorCode.LOCKED_RESOURCE,"所选草稿不是当前本人草稿");var doc=data.read("taskDocument",c);result.set("taskDocument",doc);result.set("task",data.read("task",doc.path("taskId").asText()));result.set("checkpoint",result.get("segmentationCheckpoint"));result.set("textVersion",result.get("text"));result.put("fixture",false);if(!result.hasNonNull("graph"))result.set("graph",mapper.createObjectNode().put("status","INVALID"));return result;}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public ObjectNode graph(Actor actor,String type,String id,Integer layoutVersion){var snapshot=reader.read(actor,type,id);if("ANNOTATION_VERSION".equals(type))snapshot=versions.snapshot(id);ObjectNode g;if("DRAFT".equals(type)){var d=(ObjectNode)snapshot.get("draft");require(d.hasNonNull("graphId"),ErrorCode.NOT_FOUND,"请先显式校验草稿以生成图记录");g=data.read("graph",d.path("graphId").asText());}else{require(snapshot.hasNonNull("graph"),ErrorCode.NOT_FOUND,"快照没有论证图");g=(ObjectNode)snapshot.get("graph");}int selectedLayout=0;if("DRAFT".equals(type))selectedLayout=layout(g,layoutVersion).path("layoutVersion").asInt(0);else{for(var l:snapshot.path("layouts"))if(layoutVersion==null||layoutVersion==l.path("layoutVersion").asInt())selectedLayout=Math.max(selectedLayout,l.path("layoutVersion").asInt());require(layoutVersion==null||selectedLayout==layoutVersion,ErrorCode.NOT_FOUND,"冻结布局版本不存在");}return mapper.createObjectNode().put("graphId",g.path("id").asText()).put("status",g.path("status").asText()).put("layoutVersion",selectedLayout);}
    private ObjectNode layout(ObjectNode g,Integer version){var layouts=data.find("layout","graphId",g.path("id").asText()).stream().filter(l->compatible(g,l)).toList();if(version!=null){require(version>=1,ErrorCode.VALIDATION_ERROR,"布局版本必须为正整数");return layouts.stream().filter(l->l.path("layoutVersion").asInt()==version).findFirst().orElseThrow(()->new BusinessException(ErrorCode.NOT_FOUND,"布局版本不存在"));}return layouts.stream().max(Comparator.comparingInt(l->l.path("layoutVersion").asInt())).orElse(mapper.createObjectNode());}
    private boolean compatible(ObjectNode g,ObjectNode l){var es=set(g.path("elementIds"));var rs=set(g.path("relationIds"));var seen=new HashSet<String>();for(var p:l.path("nodePositions")){String id=p.path("targetId").asText();if(!seen.add(id)||!("ELEMENT".equals(p.path("targetKind").asText())?es.contains(id):"RELATION".equals(p.path("targetKind").asText())&&rs.contains(id)))return false;}var all=new HashSet<>(es);all.addAll(rs);return all.equals(seen);}
    @Transactional
    public ObjectNode resetGraph(Actor actor,String id,String key,int expected,ObjectNode body){require(body.isEmpty(),ErrorCode.VALIDATION_ERROR,"不接受额外字段");var d=drafts.lockDraft(actor,id);var cached=drafts.replay(actor,"RESET-GRAPH:"+id,key,body);if(cached!=null)return cached;drafts.writable(d);drafts.version(d,expected,"AnnotationDraft");var before=d.deepCopy();if(d.hasNonNull("graphId")){String graphId=d.path("graphId").asText();var g=data.lock("graph",graphId);require(id.equals(g.path("ownerId").asText())&&"DRAFT".equals(g.path("ownerType").asText()),ErrorCode.FORBIDDEN,"图不属于本人草稿");jdbc.update("UPDATE workflow_records SET object_kind='retiredGraph' WHERE object_kind='graph' AND object_id=?",graphId);for(var l:data.find("layout","graphId",graphId))jdbc.update("UPDATE workflow_records SET object_kind='retiredLayout' WHERE object_kind='layout' AND object_id=?",l.path("id").asText());d.putNull("graphId");drafts.touchDraft(d,actor);data.replace("draft",d);}var response=mapper.createObjectNode().put("reset",true);drafts.saveReceipt(actor,"RESET-GRAPH:"+id,key,body,response,before,d);return response;}
    @Transactional
    public ObjectNode saveLayout(Actor actor,String id,String key,ObjectNode body){validator.validate("GR03",body);var g=data.read("graph",VersionJson.uuid(id));require("DRAFT".equals(g.path("ownerType").asText()),ErrorCode.FORBIDDEN,"不能修改冻结布局");var d=drafts.lockDraft(actor,g.path("ownerId").asText());g=data.lock("graph",id);require(d.path("graphId").equals(g.path("id")),ErrorCode.GRAPH_INVALID,"草稿图来源不一致");var cached=drafts.replay(actor,"GR03:"+id,key,body);if(cached!=null)return cached;drafts.writable(d);require(body.path("canvasWidth").asInt()>0&&body.path("canvasHeight").asInt()>0,ErrorCode.VALIDATION_ERROR,"画布尺寸须为正整数");var result=engine.inspect(d.path("id").asText(),drafts.orderedElements(d.path("id").asText()),relations(d.path("id").asText()),parts(relations(d.path("id").asText())));var nodes=new HashMap<String,String>();result.graph().nodes().forEach(n->nodes.put(n.id(),n.kind()));var seen=new HashSet<String>();for(var p:body.path("nodePositions"))require(p.path("targetKind").asText().equals(nodes.get(p.path("targetId").asText()))&&seen.add(p.path("targetId").asText()),ErrorCode.GRAPH_INVALID,"布局必须引用当前草稿图节点且不能重复");require(seen.equals(nodes.keySet()),ErrorCode.GRAPH_INVALID,"布局必须覆盖全部节点");var before=d.deepCopy();var l=mapper.createObjectNode();VersionJson.stamp(l,actor.id(),VersionJson.now());l.put("graphId",id).put("layoutVersion",data.find("layout","graphId",id).stream().mapToInt(row->row.path("layoutVersion").asInt()).max().orElse(0)+1);for(String f:List.of("canvasWidth","canvasHeight","nodePositions"))l.set(f,body.get(f));drafts.append("layout",l);drafts.touchDraft(d,actor);data.replace("draft",d);var response=mapper.createObjectNode().put("layoutVersion",l.path("layoutVersion").asInt());drafts.saveReceipt(actor,"GR03:"+id,key,body,response,before,d);return response;}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public ObjectNode workspace(Actor actor,String c){var result=drafts.context(actor,c);if(!result.hasNonNull("draft"))return result;String id=result.path("draft").path("id").asText();var rs=relations(id);var ps=parts(rs);var inspection=engine.inspect(id,drafts.orderedElements(id),rs,ps);result.set("relations",mapper.valueToTree(rs));result.set("participants",mapper.valueToTree(ps));result.set("nodes",mapper.valueToTree(inspection.graph().nodes()));result.set("edges",mapper.valueToTree(inspection.graph().edges()));result.set("issues",mapper.valueToTree(inspection.issues()));if(result.path("draft").hasNonNull("graphId")){var g=data.read("graph",result.path("draft").path("graphId").asText());result.set("graph",g);result.set("layout",layout(g,null));}else result.putNull("graph");return result;}
}
